head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > E > onerror]<br/>Image 컴포넌트에 표시할 이미지를 불러오지 못했을 때 발생합니다.",
    "validation" : [
        "Image 컴포넌트에 표시할 이미지를 불러오지 못했을 때 발생합니다.",
        "이벤트 객체 e (Event) 가 핸들러에 전달되어야 합니다.",
        "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다.",
        "존재하지 않는 경로, 잘못된 주소, 읽을 수 없는 파일 등으로 이미지 로딩에 실패하면 발생합니다.",
        "이미지 로딩에 성공한 경우 발생하는 이벤트는 지원하지 않습니다.",
        "Image 컴포넌트가 비활성화(disabled) 상태이면 이미지 로딩에 실패해도 onerror 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정 (유효 이미지)
    con_src.setValue("/img/png.png");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    // 조건 값 조회
    let cSrc = con_src.getValue();
    let cDisabled = con_disabled.getText();

    // 테스트 참고 라벨
    let strLabel = "";
    strLabel += "[전제] src = " + cSrc;
    strLabel += " / disabled = " + (cDisabled === "" ? "미설정" : cDisabled) + "\n";
    strLabel += "[절차] src 조건에서 유효 이미지 또는 로딩 실패 값(존재하지 않는 경로 / 잘못된 주소 / 읽을 수 없는 파일)을 고르고 Target 재생성 버튼을 클릭해 이미지를 다시 요청합니다.\n";
    strLabel += "[확인] 리턴 값 확인 영역에 onerror 이벤트 발생 로그가 출력되는지 확인합니다. 유효 이미지로 재생성한 경우에는 이미지가 표시되고 로그가 출력되지 않아야 합니다.";

    await $c.gcm.createLabel('label="' + strLabel + '"', '', 'label1');

    // 조건 설정
    let properties = {
        disabled : cDisabled,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onerror"]);

    // src 를 con 값으로 가변해야 하므로 공통 함수($c.gcm.createBasicImage 는 src 고정) 대신 직접 생성한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + cList + ' ' + eList + ' src="' + cSrc + '"></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);
}



// validation 1, 2, 3, 4, 5, 6 판정 출력
scwin.target1_onerror = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onerror 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
